def decrypt_repeating_cipher(n, t):
    m = len(t)
    s = []
    j = 0

    for i in range(1, m + 1):
        while j < n and t[j] == chr(ord('a') + i - 1):
            j += 1
        s.append(chr(ord('a') + i - 1))

    return ''.join(s)

