def decrypt_repeating_cipher(n, t):
    result = []
    index = 0
    for i in range(1, n + 1):
        substring = t[index:index + i]
        if substring.count(substring[0]) == i:
            result.append(substring[0])
            index += i
    return ''.join(result)

